() => {
  const selects = Array.from(document.querySelectorAll('select')).map(s => ({
    id: s.id, name: s.name, className: s.className,
    value: s.value,
    options: Array.from(s.options).map(o => ({value: o.value, text: o.textContent}))
  }));
  // also look for combobox-like buttons
  const combos = Array.from(document.querySelectorAll('[role="combobox"], [role="listbox"]')).map(e => ({role: e.getAttribute('role'), text: e.textContent.slice(0,80)}));
  return {selects, combos, url: location.href};
}

async () => {
  const start = Date.now();
  while (Date.now() - start < 10000) {
    if (!document.body.innerText.includes('AI 正在解析 Schema')) return {done: true, waitedMs: Date.now()-start};
    await new Promise(r => setTimeout(r, 1000));
  }
  return {done: false, waitedMs: Date.now()-start};
}

