() => {
  const btns = Array.from(document.querySelectorAll('button')).filter(b => b.textContent.includes('回答有帮助') || b.textContent.includes('回答不准确'));
  return btns.map(b => ({
    text: b.textContent.trim(),
    html: b.innerHTML.slice(0, 200),
    className: b.className,
    disabled: b.disabled
  }));
}

() => {
  const btns = Array.from(document.querySelectorAll('button')).filter(b => {
    const label = (b.getAttribute('aria-label')||'') + (b.title||'') + b.textContent;
    return label.includes('有帮助') || label.includes('不准确') || b.textContent.includes('👍') || b.textContent.includes('👎');
  });
  return btns.map(b => ({
    text: b.textContent.trim(),
    ariaLabel: b.getAttribute('aria-label'),
    title: b.title,
    className: b.className,
    disabled: b.disabled,
    outerStart: b.outerHTML.slice(0, 300)
  }));
}

() => {
  const btns = Array.from(document.querySelectorAll('button')).filter(b => {
    const label = b.getAttribute('aria-label')||'';
    return label.includes('有帮助') || label.includes('不准确');
  });
  const toast = Array.from(document.querySelectorAll('div,span,p')).map(e => e.textContent.trim()).find(t => t.includes('感谢反馈'));
  return {
    buttons: btns.map(b => ({ariaLabel: b.getAttribute('aria-label'), className: b.className, disabled: b.disabled})),
    toastPresent: !!toast,
    toastText: toast || null
  };
}

() => {
  const s = document.querySelector('select');
  if (!s) return {found: false};
  return {found: true, value: s.value, selectedText: s.options[s.selectedIndex]?.textContent,
    options: Array.from(s.options).map(o => o.textContent)};
}

