() => {
  const btns = Array.from(document.querySelectorAll('button[aria-label="回答有帮助"]'));
  const target = btns[btns.length - 1]; // latest answer's like button
  target.scrollIntoView({block: 'center', behavior: 'instant'});
  const rect = target.getBoundingClientRect();
  return {scrolled: true, top: rect.top, visible: rect.top >= 0 && rect.top <= window.innerHeight};
}
